import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('lifecycle and derivation', async () => {
  const h = await createHost();
  assert.equal(await h.run('r'), null);
  assert.equal((await h.taskStarted('r', 0)).ok, false);
  assert.deepEqual(await h.start('r'), { ok: true });
  assert.equal((await h.start('r')).ok, false);
  assert.deepEqual(await h.run('r'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued' });
  assert.equal((await h.taskStarted('r', 3)).ok, false);
  assert.equal((await h.taskStarted('r', 0.5)).ok, false);
  assert.equal((await h.taskCompleted('r', 0)).ok, false);
  await h.taskStarted('r', 0);
  assert.equal((await h.run('r'))!.status, 'running');
  await h.taskCompleted('r', 0);
  assert.equal((await h.run('r'))!.status, 'running');
  await h.taskStarted('r', 1); await h.taskEvicted('r', 1);
  await h.taskStarted('r', 2); await h.taskCompleted('r', 2);
  assert.equal((await h.run('r'))!.status, 'running');
  await h.taskRequeued('r', 1); await h.taskStarted('r', 1); await h.taskCompleted('r', 1);
  assert.equal((await h.run('r'))!.status, 'completed');
  assert.equal((await h.cancel('r')).ok, false);
});

test('all evicted, failure, cancel', async () => {
  const h = await createHost();
  await h.start('a');
  for (const t of [0, 1, 2]) { await h.taskStarted('a', t); await h.taskEvicted('a', t); }
  assert.equal((await h.run('a'))!.status, 'evicted');
  await h.taskRequeued('a', 0); await h.taskStarted('a', 0); await h.taskFailed('a', 0);
  assert.equal((await h.run('a'))!.status, 'failed');
  assert.equal((await h.taskRetried('a', 1)).ok, false);
  assert.deepEqual(await h.taskRequeued('a', 1), { ok: true });
  assert.equal((await h.run('a'))!.status, 'failed');
  assert.deepEqual(await h.taskRetried('a', 0), { ok: true });
  assert.equal((await h.run('a'))!.status, 'running');
  assert.equal((await h.taskRetried('a', 0)).ok, false);

  await h.start('c');
  for (const t of [0, 1, 2]) { await h.taskStarted('c', t); await h.taskFailed('c', t); }
  assert.equal((await h.run('c'))!.status, 'failed');
  assert.equal((await h.cancel('c')).ok, false);
  for (const t of [0, 1, 2]) assert.deepEqual(await h.taskRetried('c', t), { ok: true });
  assert.equal((await h.run('c'))!.status, 'queued');
  await h.taskStarted('c', 0); await h.taskFailed('c', 0);
  assert.deepEqual(await h.cancel('c'), { ok: true });
  assert.deepEqual(await h.run('c'), { status: 'failed', task0: 'failed', task1: 'cancelled', task2: 'cancelled' });
  assert.deepEqual(await h.taskRetried('c', 0), { ok: true });
  assert.equal((await h.run('c'))!.status, 'running');
  await h.taskStarted('c', 0); await h.taskCompleted('c', 0);
  assert.equal((await h.run('c'))!.status, 'cancelled');
  assert.equal((await h.taskRetried('c', 0)).ok, false);
});

test('cancelTask', async () => {
  const h = await createHost();
  assert.equal((await h.cancelTask('x', 0)).ok, false);
  await h.start('d');
  assert.equal((await h.cancelTask('d', 3)).ok, false);
  assert.deepEqual(await h.cancelTask('d', 0), { ok: true });
  assert.deepEqual(await h.run('d'), { status: 'running', task0: 'cancelled', task1: 'queued', task2: 'queued' });
  assert.equal((await h.cancelTask('d', 0)).ok, false);
  await h.taskStarted('d', 1); await h.taskEvicted('d', 1);
  assert.deepEqual(await h.cancelTask('d', 1), { ok: true });
  await h.taskStarted('d', 2); await h.taskFailed('d', 2);
  assert.equal((await h.run('d'))!.status, 'failed');
  assert.equal((await h.cancelTask('d', 2)).ok, false);
  await h.taskRetried('d', 2);
  assert.equal((await h.run('d'))!.status, 'running');
  await h.taskStarted('d', 2);
  assert.deepEqual(await h.cancelTask('d', 2), { ok: true });
  assert.equal((await h.run('d'))!.status, 'cancelled');
  assert.equal((await h.taskRetried('d', 2)).ok, false);

  await h.start('e');
  for (const t of [0, 1]) { await h.taskStarted('e', t); await h.taskCompleted('e', t); }
  await h.cancelTask('e', 2);
  assert.equal((await h.run('e'))!.status, 'cancelled');

  await h.start('b');
  await h.taskStarted('b', 0); await h.taskCompleted('b', 0);
  assert.deepEqual(await h.cancel('b'), { ok: true });
  assert.deepEqual(await h.run('b'), { status: 'cancelled', task0: 'completed', task1: 'cancelled', task2: 'cancelled' });
});

