import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';

test('lifecycle and derivation', async () => {
  const h = await createHost();
  assert.equal(await h.run('r'), null);
  assert.equal((await h.taskStarted('r', 0)).ok, false);
  assert.deepEqual(await h.start('r'), { ok: true });
  assert.equal((await h.start('r')).ok, false);
  assert.deepEqual(await h.run('r'), { status: 'queued', task0: 'queued', task1: 'queued', task2: 'queued', paused: false });
  assert.equal((await h.taskStarted('r', 3)).ok, false);
  assert.equal((await h.taskStarted('r', 0.5)).ok, false);
  assert.equal((await h.taskCompleted('r', 0)).ok, false);
  await h.taskStarted('r', 0);
  assert.equal((await h.run('r'))!.status, 'running');
  await h.taskCompleted('r', 0);
  assert.equal((await h.run('r'))!.status, 'running');
  await h.taskStarted('r', 1); await h.taskEvicted('r', 1);
  await h.taskStarted('r', 2); await h.taskCompleted('r', 2);
  assert.equal((await h.run('r'))!.status, 'running');
  await h.taskRequeued('r', 1); await h.taskStarted('r', 1); await h.taskCompleted('r', 1);
  assert.equal((await h.run('r'))!.status, 'completed');
  assert.equal((await h.cancel('r')).ok, false);
});

